Theorem opdel_sr : HeapSR_iface.opdel_sr_stmt HS.
Proof. try hcb. try hsb. apply free_sr_at. intros. eapply (F_opnew.opdel_spec _ _ _ rfree_stmt_mirror); eauto. Qed.

Theorem opdel2_sr : HeapSR_iface.opdel2_sr_stmt HS.
Proof. try hcb. try hsb. apply free_sr_at. intros. eapply (F_opnew.opdel_sz_spec _ _ _ rfree_stmt_mirror); eauto. Qed.

Theorem opdel_null_sr : HeapSR_iface.opdel_null_sr_stmt_at HS HeapSR_iface.ROPDEL.
Proof. try hcb. try hsb.
  unfold HeapSR_iface.opdel_null_sr_stmt_at. cbn [HeapSR_iface.hs_SR HS]. intros until mo. intros HH HL.
  unfold HeapSR_iface.opdel_null_post.
  eapply sreach_mono; [eapply (cj_evt_sreach rsegs _ _ mo HH HL); apply (F_opnew.opdel_null_spec); reflexivity|].
  intros c [H1 H2]. split; [exact H1| exact H2].
Qed.

Theorem opdel2_null_sr : HeapSR_iface.opdel_null_sr_stmt_at HS HeapSR_iface.ROPDEL2.
Proof. try hcb. try hsb.
  unfold HeapSR_iface.opdel_null_sr_stmt_at. cbn [HeapSR_iface.hs_SR HS]. intros until mo. intros HH HL.
  unfold HeapSR_iface.opdel_null_post.
  eapply sreach_mono; [eapply (cj_evt_sreach rsegs _ _ mo HH HL); apply (F_opnew.opdel_sz_null_spec); reflexivity|].
  intros c [H1 H2]. split; [exact H1| exact H2].
Qed.

